mkdir -p /tmp/room41-test && cd /tmp/room41-test && cat > /tmp/room41-test/make-test.mjs <<'EOF'
// Scratch harness: a stand-in shell around the P7 west bedroom back (the real shell is other workers' parts).
import { Grid } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
import { SITE_SIZE } from "/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/millkit3/crew/part-48/vocab/base.mjs";
import { build } from "/Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/millkit3/crew/part-48/parts/room-41.mjs";

const out = process.argv[2];
const g = new Grid(SITE_SIZE);
g.fill([84, 7, 10], [89, 7, 17], "jungle_planks");              // floor y7 (stand y8)
g.fill([84, 12, 10], [89, 12, 17], "stone");                    // roof over the room
g.fill([85, 8, 13], [88, 11, 13], "stone");                     // north wall z13 ...
g.set(86, 8, 13, "air"); g.set(86, 9, 13, "air");              // ... with the door (86, 8..9, 13)
g.fill([85, 8, 16], [88, 11, 16], "stone");                    // back wall z16
g.fill([85, 8, 14], [85, 11, 15], "stone");                    // west wall x85
g.fill([88, 8, 14], [88, 11, 15], "stone");                    // east wall x88 (stair side, stand-in)
g.set(85, 9, 14, "glass_pane"); g.set(85, 10, 14, "glass_pane"); // west window at z14
build(g);
g.save(out);
EOF
cat > /tmp/room41-test/rooms.json <<'EOF'
{"entrance":[86,8,11],"rooms":[{"name":"P7 west bedroom back","box":[86,8,14,87,11,15]}]}
EOF
MCD="/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs"
node /tmp/room41-test/make-test.mjs /tmp/room41-test/test.nbt && node $MCD room /tmp/room41-test/test.nbt --rooms /tmp/room41-test/rooms.json --only "P7 west bedroom back" 2>&1 | tail -50; date

